import{AGENT_INFO_FORBIDDEN_CODE,AGENT_INFO_FORBIDDEN_MESSAGE}from"#protocol/routes.js";import{ClientError}from"#client/client-error.js";function isAgentInfoForbidden(e){return e instanceof ClientError&&e.status===403&&e.code===AGENT_INFO_FORBIDDEN_CODE}function formatAgentInfoForbiddenMessage(e){return`${e} refused GET /eve/v1/info. ${AGENT_INFO_FORBIDDEN_MESSAGE}`}export{formatAgentInfoForbiddenMessage,isAgentInfoForbidden};